{
  "rule": "Robin starts at a hidden mood score of 0; each apology or gift adds 1 and each insult subtracts 1, and Robin is warm only if the final score is positive (equivalently, #apologies + #gifts > #insults).",
  "commitments": [
    {
      "events": ["apologise", "apologise", "insult"],
      "predict": "warm",
      "why": "If this came out cold, two apologies would not outweigh one later insult, suggesting recency or a stronger insult effect than the rule allows."
    },
    {
      "events": ["insult", "gift", "gift"],
      "predict": "warm",
      "why": "If this came out cold, one insult would outweigh two gifts, contradicting the equal +1/-1 balance."
    },
    {
      "events": ["insult", "apologise", "apologise"],
      "predict": "warm",
      "why": "If this came out cold, two apologies would not offset one insult, indicating apologies are weaker or insults heavier than in the rule."
    },
    {
      "events": ["apologise", "insult", "apologise"],
      "predict": "warm",
      "why": "If this came out cold, an intervening insult would cancel two apologies, contradicting equal positive and negative weights."
    },
    {
      "events": ["gift", "insult", "apologise"],
      "predict": "warm",
      "why": "If this came out cold, a gift plus an apology would not outweigh one insult, showing the positive actions are too weak relative to insults."
    }
  ]
}

{
  "rule": "Insults count against Robin while apologies and gifts count in Robin's favour; Robin ends warm exactly when apologies plus gifts outnumber insults.",
  "commitments": [
    {
      "events": ["gift"],
      "predict": "warm",
      "why": "If this came out cold, a single gift would not count as a positive action, contradicting the rule that one positive outweighs zero negatives."
    },
    {
      "events": ["insult", "gift", "gift"],
      "predict": "warm",
      "why": "If this came out cold, two gifts could not outweigh one insult, contradicting equal positive weight for gifts against insults."
    },
    {
      "events": ["apologise", "insult", "gift"],
      "predict": "warm",
      "why": "If this came out cold, the gift would not break the apology-insult tie, contradicting gifts counting as positives."
    },
    {
      "events": ["gift", "insult", "apologise"],
      "predict": "warm",
      "why": "If this came out cold, the same set of actions as apology-insult-gift would depend on order, contradicting the net-count rule."
    },
    {
      "events": ["gift", "gift"],
      "predict": "warm",
      "why": "If this came out cold, gifts would not accumulate as positive counts, contradicting the rule that positives strictly exceed insults."
    }
  ]
}
